h q[1];
h q[2];
h q[3];
h q[4];
measure q[0] -> c[0];
measure q[1] -> c[1];
measure q[2] -> c[2];
measure q[3] -> c[3];
measure q[4] -> c[4];
"""

def run_and_analyze(circuit, aer_sim):
    # Transpile and run the circuit
    transpiled = transpile(circuit, aer_sim)
    result = aer_sim.run(transpiled, shots=100).result()
    counts = result.get_counts()

    # Collect measurement outcomes (only input qubits, ignore output)
    outcomes = []
    for bitstring, count in counts.items():
        # bitstring is in reverse order (qubit 0 is rightmost)
        # We only care about the first 5 bits (input qubits)
        # The bitstring length is 10, but we only measured input qubits, so the last 5 bits are '0' (since not measured)
        # Actually, we measured only input qubits, so the bitstring has 10 bits, with the last 5 always '0'.
        # We'll take the first 5 bits (from left) as the input measurement.
        # In Qiskit, bitstring is ordered with qubit 0 as the least significant bit (rightmost).
        # So for 10 qubits, the bitstring is c9 c8 ... c0.
        # We measured q0..q4 -> c0..c4. So the rightmost 5 bits correspond to q0..q4.
        # We'll extract the rightmost 5 bits.
        input_bits = bitstring[-5:]  # last 5 characters
        # Convert to list of ints
        bits = [int(b) for b in input_bits]
        outcomes.extend([bits] * count)

    # Build matrix over GF(2) for equations y·s = 0 mod 2
    # We have many vectors y (each outcome). We want s such that y·s = 0 for all y.
    # Solve via Gaussian elimination.
    if not outcomes:
        # Fallback: return random string
        return '00000'

    # Convert to numpy array
    A = np.array(outcomes, dtype=int)
    # We need to find a non-zero vector s in the nullspace of A over GF(2).
    # Since the function is three-to-one, we expect a one-dimensional nullspace? Not sure.
    # We'll perform Gaussian elimination over GF(2).
    m, n = A.shape
    # Augment with zero column for homogeneous system
    # We'll perform elimination on A.
    pivot_cols = []
    row = 0
    for col in range(n):
        # Find pivot row
        pivot = -1
        for i in range(row, m):
            if A[i, col] == 1:
                pivot = i
                break
        if pivot == -1:
            continue
        # Swap rows
        A[[row, pivot]] = A[[pivot, row]]
        # Eliminate below
        for i in range(row+1, m):
            if A[i, col] == 1:
                A[i] = (A[i] + A[row]) % 2
        pivot_cols.append(col)
        row += 1
        if row == m:
            break
    # Now back substitution to find nullspace basis
    # We'll find one solution by setting free variables to 1.
    # Since we expect a unique non-zero s (up to scaling), we can set the last free variable to 1.
    # Determine free columns
    free_cols = [c for c in range(n) if c not in pivot_cols]
    if not free_cols:
        # No free variables, only trivial solution
        return '00000'
    # Set the first free variable to 1, others to 0
    s = np.zeros(n, dtype=int)
    # We need to solve for pivot variables.
    # We'll do back substitution from bottom.
    # First, set free variables
    for col in free_cols:
        s[col] = 0
    # Set the first free variable to 1
    s[free_cols[0]] = 1
    # Now back substitute for pivot variables
    for i in range(len(pivot_cols)-1, -1, -1):
        col = pivot_cols[i]
        # Find the row where this pivot is 1
        row_idx = i
        # Compute sum of other variables in that row
        total = 0
        for j in range(col+1, n):
            total += A[row_idx, j] * s[j]
        s[col] = total % 2

    # Convert s to string
    prediction = ''.join(str(int(x)) for x in s)
    return prediction
